let cleanse_interface_expected_definitions_v1=[
 ("bp_e2_cleanse_call_post",parse_term "forall m pc stackpointer ra p n s t.\n    bp_e2_cleanse_call_post pc stackpointer ra p n m s t <=>\n    read RIP t = ra /\\\n    val (read RSP t) = val stackpointer + 8 /\\\n    (forall i. i < n ==> read memory t (word_add p (word i)) = word 0) /\\\n    (forall a. ~assurance_region p n (val a) ==> read memory t a = m a) /\\\n    bytes_loaded t (word pc) openssl_cleanse_mc /\\\n    read (memory :> bytes64 stackpointer) t = ra /\\\n    (MAYCHANGE [RIP; RSP; RAX; RDI; RSI] ,,\n     MAYCHANGE SOME_FLAGS ,,\n     MAYCHANGE [memory :> bytes (p,n)] ,,\n     MAYCHANGE [events])\n    s\n    t",bp_e2_cleanse_call_post);
 ("bp_e2_cleanse_public_pre",parse_term "forall file_bytes initial_rw padding stackpointer ra p n m s rp ordinary xp wp a.\n    bp_e2_cleanse_public_pre file_bytes initial_rw padding stackpointer ra p\n    n\n    m\n    rp\n    wp\n    xp\n    ordinary\n    (s,a) <=>\n    clw_file_code file_bytes /\\\n    fb_full_image file_bytes initial_rw padding m /\\\n    bp_e2_cleanse_pre 270800848 stackpointer ra p n m rp wp xp ordinary s /\\\n    (forall addr.\n         lw_image_domain addr\n         ==> rp addr /\\\n             ordinary addr /\\\n             (xp addr <=> lw_execute addr) /\\\n             (wp addr <=> lw_image_write addr)) /\\\n    assurance_canonical48 (val (read ABI_FS_BASE a))",bp_e2_cleanse_public_pre);
 ("bp_e2_cleanse_public_post",parse_term "forall stackpointer ra p n m s a t.\n    bp_e2_cleanse_public_post stackpointer ra p n m s a t <=>\n    bp_e2_cleanse_call_post 270800848 stackpointer ra p n m s (FST t) /\\\n    SND t = a /\\\n    abi_required_controls_preserved a (SND t)",bp_e2_cleanse_public_post);
 ("bp_e2_cleanse_pre",parse_term "forall m ra s xp rp wp ordinary pc p n stackpointer.\n    bp_e2_cleanse_pre pc stackpointer ra p n m rp wp xp ordinary s <=>\n    n < 2 EXP 64 /\\\n    pc + 97 <= 2 EXP 64 /\\\n    bytes_loaded s (word pc) openssl_cleanse_mc /\\\n    read RIP s = word pc /\\\n    read RSP s = stackpointer /\\\n    read (memory :> bytes64 stackpointer) s = ra /\\\n    C_ARGUMENTS [p; word n] s /\\\n    read memory s = m /\\\n    val stackpointer MOD 16 = 8 /\\\n    val stackpointer + 8 < 2 EXP 64 /\\\n    assurance_canonical48 (val ra) /\\\n    ~(ra = word pc) /\\\n    (read DF s <=> false) /\\\n    ~bit 18 (read rflags s) /\\\n    assurance_span_ok (\\a. xp a /\\ ordinary a) pc 97 /\\\n    assurance_span_ok (\\a. rp a /\\ ordinary a) (val stackpointer) 8 /\\\n    assurance_span_ok (\\a. wp a /\\ ordinary a) (val p) n /\\\n    (forall a. ~(assurance_region p n a /\\ assurance_region (word pc) 97 a)) /\\\n    (forall a.\n         ~(assurance_region p n a /\\ assurance_region stackpointer 8 a))",bp_e2_cleanse_pre);
 ("bp_e2_cleanse_allowed_read",parse_term "forall rp ordinary stackpointer a.\n    bp_e2_cleanse_allowed_read rp ordinary stackpointer a <=>\n    rp a /\\ ordinary a /\\ assurance_region stackpointer 8 a",bp_e2_cleanse_allowed_read);
 ("bp_e2_cleanse_allowed_write",parse_term "forall wp ordinary p n a.\n    bp_e2_cleanse_allowed_write wp ordinary p n a <=>\n    wp a /\\ ordinary a /\\ assurance_region p n a",bp_e2_cleanse_allowed_write);
 ("bp_e2_cleanse_allowed_fetch",parse_term "forall xp ordinary pc a.\n    bp_e2_cleanse_allowed_fetch xp ordinary pc a <=>\n    xp a /\\ ordinary a /\\ assurance_region (word pc) 97 a",bp_e2_cleanse_allowed_fetch);
 ("cleanse_functional_steps",parse_term "forall n p.\n    cleanse_functional_steps p n =\n    (if n < 15\n     then 4 * n + 7\n     else let a = (8 - val p MOD 8) MOD 8 in\n          9 + 6 * a + 5 * (n - a) DIV 8 + 4 * (n - a) MOD 8)",cleanse_functional_steps);
 ("cleanse_access_count",parse_term "forall n p.\n    cleanse_access_count p n =\n    (if n < 15\n     then 4 * n + 7\n     else let a = (8 - val p MOD 8) MOD 8 in\n          let k = (n - a) DIV 8 in\n          let r = (n - a) MOD 8 in 9 + 6 * a + 5 * k + 4 * r)",cleanse_access_count);
 ("cleanse_access_covered_step",parse_term "forall rp wp xp remaining s' pc s.\n    cleanse_access_covered_step pc rp wp xp remaining s s' <=>\n    assurance_zero_step rp wp xp remaining s s' /\\\n    (exists off len inst.\n         read RIP s = word (pc + off) /\\\n         abi_cleanse_site off len inst /\\\n         x86_decode s (read RIP s) (len,inst))",cleanse_access_covered_step);
 ("cleanse_access_return_post",parse_term "forall ra stackpointer s pc.\n    cleanse_access_return_post pc stackpointer ra s <=>\n    read RIP s = ra /\\\n    read RSP s = word_add stackpointer (word 8) /\\\n    bytes_loaded s (word pc) openssl_cleanse_mc",cleanse_access_return_post);
 ("assurance_checked_run",parse_term "(assurance_checked_run 0 P C s <=> P s) /\\\n(assurance_checked_run (SUC n) P C s <=>\n (exists s'. x86 s s') /\\\n (forall s'. x86 s s' ==> C (SUC n) s s' /\\ assurance_checked_run n P C s'))",assurance_checked_run);
 ("assurance_step_policy",parse_term "forall xp s' s rp wp.\n    assurance_step_policy rp wp xp s s' <=>\n    (exists len inst d.\n         x86_decode s (read RIP s) (len,inst) /\\\n         assurance_span_ok xp (val (read RIP s)) len /\\\n         read events s' = APPEND d (read events s) /\\\n         ALL (assurance_event_policy rp wp) d)",assurance_step_policy);
 ("assurance_zero_step",parse_term "forall rp wp xp remaining s s'.\n    assurance_zero_step rp wp xp remaining s s' <=>\n    assurance_step_policy rp wp xp s s' /\\\n    (remaining = 1 ==> assurance_actual_ret 2 s s')",assurance_zero_step);
 ("assurance_event_policy",parse_term "forall e rp wp.\n    assurance_event_policy rp wp e <=>\n    (match e with\n       EventLoad (adr,width) -> assurance_span_ok rp (val adr) width\n     | EventStore (adr,width) -> assurance_span_ok wp (val adr) width\n     | _ -> true)",assurance_event_policy);
 ("assurance_fetch_policy",parse_term "forall xp obs.\n    assurance_fetch_policy xp obs <=>\n    assurance_span_ok xp (val (FST obs)) (FST (SND obs))",assurance_fetch_policy);
 ("assurance_region",parse_term "forall a p n. assurance_region p n a <=> val p <= a /\\ a < val p + n",assurance_region);
