 ("abi_cleanse_scalar_extended_step",parse_term "forall s s' a' a.\n    abi_cleanse_scalar_extended_step (s,a) (s',a') <=>\n    (exists len inst.\n         x86_decode s (read RIP s) (len,inst) /\\\n         (RIP := word_add (read RIP s) (word len) ,, x86_execute inst) s s' /\\\n         (abi_cleanse_scalar_instruction inst ==> a' = a))",abi_cleanse_scalar_extended_step);
