 ("clw_full_pre",parse_term "forall file_bytes initial_rw padding image high_first p n.\n    clw_full_pre file_bytes initial_rw padding image p n high_first <=>\n    fb_full_image file_bytes initial_rw padding\n    (read memory (FST (clw_machine image p n high_first))) /\\\n    bp_e2_cleanse_pre 270800848 (word 3145736) (word 4194304) p n\n    (clw_memory image p n high_first)\n    (clw_read p n)\n    (clw_write p n)\n    lw_execute\n    (clw_ordinary p n)\n    (FST (clw_machine image p n high_first)) /\\\n    fb_abi_initial_fields (SND (clw_machine image p n high_first)) /\\\n    (forall a. fb_tls_page a ==> clw_read p n a /\\ clw_ordinary p n a) /\\\n    assurance_canonical48\n    (val (read ABI_FS_BASE (SND (clw_machine image p n high_first)))) /\\\n    (forall a.\n         lw_image_domain a\n         ==> clw_read p n a /\\\n             clw_ordinary p n a /\\\n             (lw_execute a <=> lw_image_execute a) /\\\n             (clw_write p n a <=> lw_image_write a))",clw_full_pre);
 ("clw_machine",parse_term "forall image p n high_first.\n    clw_machine image p n high_first =\n    clw_state image p n high_first,fb_initial_abi",clw_machine);
 ("clw_memory",parse_term "forall image p n high_first.\n    clw_memory image p n high_first = lw_memory image p p n high_first",clw_memory);
